function eventModal(x={}){const m=modal(x.id?"Edit Event":"Add Event",formHtml([input("title","Title",x.title||"","text",true),'<label class="field">Description<textarea name="description" rows="4" required>'+esc(x.description||"")+'</textarea></label>',input("event_date","Date",x.event_date||"","date",true),select("category","Category",["Announcement","Activity","Exam","Holiday","Other"].map(v=>({value:v,label:v})),x.category||"Other"),input("image_url","Image URL",x.image_url||""),'<label class="field">Upload Image<input name="image_file" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label>',select("status","Status",[{value:"Published",label:"Published"},{value:"Draft",label:"Draft"}],x.status||"Published")],x.id?"Update Event":"Create Event"));m.querySelector("#modal-cancel").onclick=()=>m.remove();m.querySelector("#modal-form").onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target),data=Object.fromEntries(fd);const file=fd.get("image_file");if(file?.size){data.image_url=(await uploadImage(file,"events")).url}delete data.image_file;await adminPost({type:"event",id:x.id,...data});m.remove();toast("Event saved.","success");adminEvents(document.querySelector("#admin-panel"))}catch(e){toast(e.message,"error")}}}
async function adminGallery(panel){const r=await adminGet("gallery_images",{page:1,pageSize:100});panel.innerHTML='<div class="section-head"><div><p class="section-label">Gallery</p><h2>Manage Gallery</h2></div><button class="btn navy-btn" id="add-gallery">+ Add Image</button></div><div class="gallery-admin-grid">'+r.data.map(x=>'<article class="gallery-admin-card"><img src="'+esc(x.image_url)+'" alt="'+esc(x.alt_text||x.title)+'"><div><strong>'+esc(x.title)+'</strong><p>'+esc(x.category||"Other")+'</p><button class="btn btn-sm danger-btn delete-record" data-table="gallery_images" data-id="'+x.id+'">Delete</button></div></article>').join("")+'</div>';document.querySelector("#add-gallery").onclick=()=>galleryModal();document.querySelectorAll(".delete-record").forEach(b=>b.onclick=()=>deleteRecord("gallery_images",b.dataset.id,()=>adminGallery(panel)))}
function galleryModal(){const m=modal("Add Gallery Image",formHtml([input("title","Title","","text",true),input("category","Category",""),'<label class="field">Image File<input name="image_file" type="file" accept="image/png,image/jpeg,image/webp,image/gif" required></label>'+input("image_url","Image URL","","url",false)+input("alt_text","Alt Text","")],"Add Image"));m.querySelector("#modal-cancel").onclick=()=>m.remove();m.querySelector("#modal-form").onsubmit=async e=>{e.preventDefault();try{const fd=new FormData(e.target),data=Object.fromEntries(fd),file=fd.get("image_file");if(file?.size)data.image_url=(await uploadImage(file,"gallery")).url;if(!data.image_url)throw Error("Choose an image or provide an image URL.");delete data.image_file;await adminPost({type:"gallery",...data});m.remove();toast("Image added.","success");adminGallery(document.querySelector("#admin-panel"))}catch(e){toast(e.message,"error")}}}
async function adminComplaints(panel){const r=await adminGet("complaints",{page:1,pageSize:100});panel.innerHTML='<div class="section-head"><div><p class="section-label">Complaints</p><h2>Feedback & Complaints</h2></div></div>'+r.data.map(x=>'<article class="card complaint-card '+(x.status==="New"?"complaint-new":"")+'"><div class="section-head"><div><strong>'+esc(x.subject)+'</strong><p>'+esc(x.name)+' · '+esc(x.email||"No email")+'</p></div>'+pill(x.status)+'</div><div class="notice">'+esc(x.message)+'</div><div class="form-actions">'+(x.status==="New"?'<button class="btn btn-outline complaint-action" data-id="'+x.id+'" data-status="Read">Mark Read</button>':"")+(x.status!=="Resolved"?'<button class="btn navy-btn complaint-action" data-id="'+x.id+'" data-status="Resolved">Resolve</button>':"")+'</div></article>').join("")||'<p class="muted">No complaints.</p>';document.querySelectorAll(".complaint-action").forEach(b=>b.onclick=async()=>{try{await adminPost({type:"complaint-status",id:b.dataset.id,status:b.dataset.status});toast("Complaint updated.","success");adminComplaints(panel)}catch(e){toast(e.message,"error")}});adminSectionTools(panel,"Search complaints...",["New","Read","Resolved"])}
async function adminAdmissions(panel){const r=await adminGet("admission_applications",{page:1,pageSize:100});panel.innerHTML='<div class="section-head"><div><p class="section-label">Admissions</p><h2>Admission Applications</h2></div><button class="btn btn-outline" id="refresh-admissions">Refresh</button></div>'+(r.data?.length?table(["Application","Applicant","Class","Parent","Phone","Status","Submitted","Action"],r.data.map(x=>'<tr><td>'+esc(x.application_number)+'</td><td>'+esc(x.applicant_name)+'</td><td>'+esc(x.class_applied||"—")+'</td><td>'+esc(x.parent_name)+'</td><td>'+esc(x.parent_phone||"—")+'</td><td>'+pill(x.status)+'</td><td>'+new Date(x.created_at).toLocaleDateString()+'</td><td><select class="admission-status" data-id="'+x.id+'"><option value="">Change</option>'+["Pending","Under Review","Interview","Approved","Rejected"].map(s=>'<option '+(s===x.status?"selected":"")+'>'+s+'</option>').join("")+'</select></td></tr>').join("")):'<div class="notice">No admission applications yet.</div>');document.querySelector("#refresh-admissions").onclick=()=>adminAdmissions(panel);document.querySelectorAll(".admission-status").forEach(s=>s.onchange=async()=>{if(!s.value)return;try{await adminPost({type:"admission-status",id:s.dataset.id,status:s.value});toast("Admission status updated.","success");adminAdmissions(panel)}catch(e){toast(e.message,"error")}});adminSectionTools(panel,"Search admissions...",["Pending","Under Review","Interview","Approved","Rejected"])}
async function adminMessages(panel){const r=await adminGet("parent_messages",{page:1,pageSize:100});panel.innerHTML='<div class="section-head"><div><p class="section-label">Parent Communication</p><h2>Parent Messages</h2></div><button class="btn btn-outline" id="refresh-messages">Refresh</button></div>'+(r.data?.length?'<div class="message-list">'+r.data.map(x=>'<article class="dashboard-card '+(x.read_at?"":"message-unread")+'"><div class="section-head"><div><h3>'+esc(x.subject||"Parent message")+'</h3><p class="muted">From: '+esc(x.parent_profiles?.full_name||"Parent")+' · Student: '+esc(x.students?.full_name||"—")+' · '+new Date(x.created_at).toLocaleString()+'</p></div><span>'+pill(x.read_at?"Read":"Unread")+'</span></div><p>'+esc(x.body)+'</p><div class="form-actions"><button class="btn btn-sm btn-outline mark-parent-message" data-id="'+x.id+'">'+(x.read_at?"Mark Unread":"Mark Read")+'</button><button class="btn btn-sm btn-gold reply-parent-message" data-id="'+x.id+'" data-subject="'+esc(x.subject||"School message")+'">Reply</button></div></article>').join("")+'</div>':'<div class="notice">No parent messages yet.</div>');document.querySelector("#refresh-messages").onclick=()=>adminMessages(panel);document.querySelectorAll(".mark-parent-message").forEach(b=>b.onclick=async()=>{try{await adminPost({type:"message-status",id:b.dataset.id,status:b.textContent.includes("Unread")?"Read":"Unread"});adminMessages(panel)}catch(e){toast(e.message,"error")}});document.querySelectorAll(".reply-parent-message").forEach(b=>b.onclick=()=>{const m=modal("Reply to Parent",formHtml([input("subject","Subject","Re: "+b.dataset.subject),'<label class="field">Reply<textarea name="body" rows="6" required maxlength="2000"></textarea></label>'],"Send Reply"));m.querySelector("#modal-cancel").onclick=()=>m.remove();m.querySelector("#modal-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await adminPost({type:"message-reply",id:b.dataset.id,subject:f.get("subject"),body:f.get("body")});m.remove();toast("Reply sent to parent.","success");adminMessages(panel)}catch(x){toast(x.message,"error")}}});adminSectionTools(panel,"Search parent messages...",["Unread","Read"])}
async function adminSubjects(panel){
 const r=await adminGet("subjects",{page:1,pageSize:100}),classes=(await adminGet("classes")).data||[];
 panel.innerHTML='<div class="section-head"><div><p class="section-label">Academic Setup</p><h2>Classes & Subjects</h2><p class="muted">Classes are the source of truth for student placement and teacher assignments.</p></div></div>'+
 '<div class="admin-card-grid"><section class="dashboard-card"><div class="section-head"><h3>Classes</h3><button class="btn navy-btn" id="add-class">+ Add Class</button></div>'+
 (classes.length?table(["Class","Status","Actions"],classes.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+pill(x.is_active?"Active":"Inactive")+'</td><td><button class="btn btn-sm btn-outline edit-class" data-id="'+x.id+'">Edit</button> <button class="btn btn-sm danger-btn delete-class" data-id="'+x.id+'">Delete</button></td></tr>').join("")):'<p class="muted">No classes created yet.</p>')+
 '</section><section class="dashboard-card"><div class="section-head"><h3>Subjects</h3><span class="muted">'+r.data.length+' subject(s)</span></div>'+
 '<form id="subject-form" class="inline-form"><input name="name" required placeholder="Subject name"><select name="class_id"><option value="">General / all classes</option>'+classes.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('')+'</select><button class="btn navy-btn">Add Subject</button></form>'+
 '<div class="subject-list">'+r.data.map(x=>'<div class="subject-row"><span>'+esc(x.name)+(x.class_id?' — '+esc(classes.find(c=>c.id===x.class_id)?.name||"Class"):" — General")+'</span><button class="btn btn-sm danger-btn delete-record" data-table="subjects" data-id="'+x.id+'">Delete</button></div>').join("")+'</div></section></div>';
 document.querySelector("#add-class").onclick=()=>classModal();
 document.querySelectorAll(".edit-class").forEach(b=>b.onclick=()=>classModal(classes.find(x=>x.id===b.dataset.id)));
 document.querySelectorAll(".delete-class").forEach(b=>b.onclick=async()=>{if(!confirm("Delete this class? Students, subjects or assignments linked to it may prevent deletion."))return;try{await adminPost({type:"class",action:"delete",id:b.dataset.id});toast("Class deleted.","success");adminSubjects(panel)}catch(e){toast(e.message,"error")}});
 document.querySelector("#subject-form").onsubmit=async e=>{e.preventDefault();try{await adminPost({type:"subject",...Object.fromEntries(new FormData(e.target))});toast("Subject added.","success");adminSubjects(panel)}catch(e){toast(e.message,"error")}};
 document.querySelectorAll(".delete-record").forEach(b=>b.onclick=()=>deleteRecord("subjects",b.dataset.id,()=>adminSubjects(panel)));adminSectionTools(panel,"Search subjects and classes...",[...new Set(classes.map(x=>x.name).filter(Boolean)),"General"]);
}
function classModal(x={}){const title=x.id?"Edit Class":"Add Class";const m=modal(title,formHtml([input("name","Class Name",x.name||"","text",true),select("is_active","Status",[{value:"true",label:"Active"},{value:"false",label:"Inactive"}],String(x.is_active!==false))],x.id?"Update Class":"Create Class"));m.querySelector("#modal-cancel").onclick=()=>m.remove();m.querySelector("#modal-form").onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));b.is_active=b.is_active==="true";await adminPost({type:"class",id:x.id,...b});m.remove();toast("Class saved.","success");adminSubjects(document.querySelector("#admin-panel"))}catch(e){toast(e.message,"error")}}}
async function uploadImage(file,kind){if(file.size>4*1024*1024)throw Error("Image must be 4MB or smaller.");const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});return adminPost({type:"upload-image",kind,data,mime:file.type});}
async function adminSettings(panel){const r=await api("/api/dashboard-data");panel.innerHTML='<div class="section-head"><div><p class="section-label">Settings</p><h2>Administrator Settings</h2></div></div><div class="admin-card-grid"><section class="dashboard-card"><h3>Live Overview</h3><div class="stats">'+["students","teachers","parents","results"].map(k=>'<article class="stat"><small>'+k+'</small><strong>'+Number(r.stats?.[k]||0)+'</strong></article>').join("")+'</div></section><section class="dashboard-card"><h3>Administrator Credentials</h3><p class="muted">The administrator username and password are managed securely in the Vercel environment. They are not stored in Supabase and cannot be changed from this dashboard.</p><p class="muted">After changing either credential in Vercel, redeploy the project for the new credentials to take effect.</p></section><section class="dashboard-card"><h3>Security</h3><p class="muted">Administrator access uses a signed administrator session. The session expires automatically after 12 hours.</p><button class="btn btn-outline" id="signout-settings">Logout</button></section></div>';document.querySelector("#signout-settings").onclick=()=>{localStorage.removeItem("dblossom_admin_session");location.href="/admin"};adminSectionTools(panel,"Search settings...",["Overview","Credentials","Security"])}
async function deleteRecord(table,id,refresh){if(!confirm("Delete this record? This action cannot be undone."))return;try{await adminPost({type:"delete",table,id});toast("Deleted successfully.","success");refresh()}catch(e){toast(e.message,"error")}}

if(loginForm)login();render();